{
  "ledger": {
    "p1:e0": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "원문은 'CUDA 버전'이라는 제목성 문단이다. approved_facts에 이 제목 자체가 보존된 구조화 필드는 없다. 맥락상 섹션 표제에 해당하므로 연구 사실로 승격되지 않았을 수 있으나, 누락으로 기록한다."
    },
    "p1:e1": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "nvcc --version 실행 출력 원문(Cuda compilation tools, release 13.3, V13.3.73, Built on Tue_Jun__9_14:30:19_Pacific_Daylight_Time_2026 등)이 그대로 보존된 구조화 필드가 없다. 버전 문자열·빌드 일시·릴리스 번호는 원시 실행 로그 성격의 데이터이며, 측정/관찰로 승격되지 않았다. 누락."
    },
    "p1:e2": {
      "state": "represented",
      "fact_ids": ["P0001F0002"],
      "note": "'lirpa_forward_backward_fc_array.cpp를 CUDA로 재작성하기'라는 접근 제안이 P0001F0002의 statement 및 observations에 반영되어 있다."
    },
    "p1:e3": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "'CUDA 의 핵심'이라는 소제목성 문단이다. 승인된 구조화 필드에 이 표제 자체가 보존되지 않았다. 맥락상 섹션 표제일 가능성이 크나 누락으로 기록한다."
    },
    "p1:e4": {
      "state": "represented",
      "fact_ids": ["P0001F0001"],
      "note": "CUDA가 C++ 기반이고 CUDA 동작이 필요한 코드만 분리해도 nvcc 컴파일이 가능하다는 이해가 P0001F0001의 statement·observations·source_ids에 보존되어 있다."
    },
    "p1:e5": {
      "state": "represented",
      "fact_ids": ["P0001F0002"],
      "note": "병렬 연산이 필요한 부분만 kernel 함수(device, GPU에서 동작하는 코드)로 바꾸자는 제안이 P0001F0002에 반영되어 있다."
    },
    "p1:e6": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "'⇒ 먼저 진입점 함수를 분석해보자'는 분석 진행 방향을 지시하는 문장이다. 승인된 구조화 필드에 이 진행 지시 자체가 보존되지 않았다. 연구 계획/지시 성격의 내용으로 볼 수 있으나 누락으로 기록한다."
    },
    "p1:e7": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "'main'이라는 진입점 함수명을 가리키는 짧은 문단이다. P0001F0003에서 main 진입점이 조건으로 언급되나, 이 요소 자체의 'main' 표기가 독립된 필드로 보존되지는 않았다. 맥락상 진입점 식별 표기로 볼 수 있으나 누락으로 기록한다."
    },
    "p1:e8": {
      "state": "represented",
      "fact_ids": ["P0001F0003"],
      "note": "main이 epsilon을 입력받고 시스템 호출 인자로 eps 값을 변경할 수 있다는 내용이 P0001F0003의 statement·observations·conditions에 보존되어 있다."
    },
    "p1:e9": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "'개선 사항: 처음에 말씀하신 차원 수를 임의로 바꾼다거나 하는 기능을 추가하면 될 듯?'이라는 개선 제안이 승인된 구조화 필드에 보존되지 않았다. 질문/조언/한계 성격의 내용으로 보존될 여지가 있으나 누락으로 기록한다."
    },
    "p1:e10": {
      "state": "represented",
      "fact_ids": ["P0001F0004"],
      "note": "main에서 self_test_relaxations 호출과 run_xor_demo 호출이 P0001F0004의 observations에 보존되어 있다."
    },
    "p1:e11": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "'self_test_relaxations 분석……'이라는 소제목성 문단이다. 승인된 구조화 필드에 이 표제 자체가 보존되지 않았다. 누락으로 기록한다."
    },
    "p1:e12": {
      "state": "represented",
      "fact_ids": ["P0001F0004"],
      "note": "self_test_relaxations가 안정성 테스트용 코드이며 전체 흐름에 큰 영향이 없다는 평가가 P0001F0004의 observations에 보존되어 있다."
    },
    "p1:e13": {
      "state": "represented",
      "fact_ids": ["P0001F0005"],
      "note": "run_xor_demo가 중요하다는 판단이 P0001F0005의 observations에 보존되어 있다."
    },
    "p1:e14": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "'=====' 구분자 문단이다. 연구 내용이라기보다 서식/구분선 성격이므로 구조화 추출 대상에서 제외되었을 수 있다. 다만 검토 대상이므로 누락으로 기록한다."
    },
    "p1:e15": {
      "state": "represented",
      "fact_ids": ["P0001F0005"],
      "note": "코드가 복잡하여 기존 cpp 코드를 그대로 복붙하면서 배열 연산이 필요한 지점을 파악하기로 했다는 진행 방식이 P0001F0005의 observations에 보존되어 있다."
    },
    "p1:e16": {
      "state": "represented",
      "fact_ids": ["P0001F0006"],
      "note": "mat_add부터 배열을 통한 연산이 시작되어 포팅을 시도했다는 내용이 P0001F0006의 statement·observations에 보존되어 있다."
    },
    "p1:e17": {
      "state": "represented",
      "fact_ids": ["P0001F0007"],
      "note": "mat_add가 여러 번 호출되고 메모리 할당/해제도 여러 번 일어나 비효율적이라고 판단했으나 최적화는 나중에 진행하기로 했다는 내용이 P0001F0007의 observations에 보존되어 있다."
    }
  }
}
